referenceSolutions.javascript:
export function countBits(n        )           {
  const counts = Array        (n+1).fill(0); for (let i = 1; i <= n; i++) counts[i] = counts[Math.floor(i/2)] + i % 2; return counts;
}

referenceSolutions.typescript:
export function countBits(n: number): number[] {
  const counts = Array<number>(n+1).fill(0); for (let i = 1; i <= n; i++) counts[i] = counts[Math.floor(i/2)] + i % 2; return counts;
}
